use crate::storage::Database;
use rusqlite::params;
use serde_json::{json,Value};
use windows_sys::{core::GUID,Win32::{Foundation::LocalFree,System::Power::{PowerGetActiveScheme,PowerSetActiveScheme,PowerEnumerate,PowerReadFriendlyName}}};
pub fn format_guid(g:&GUID)->String{format!("{:08x}-{:04x}-{:04x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",g.data1,g.data2,g.data3,g.data4[0],g.data4[1],g.data4[2],g.data4[3],g.data4[4],g.data4[5],g.data4[6],g.data4[7])}
pub fn parse_guid(value:&str)->Result<GUID,String>{let parts:Vec<_>=value.split('-').collect();if parts.len()!=5||parts.iter().zip([8,4,4,4,12]).any(|(p,n)|p.len()!=n||!p.bytes().all(|c|c.is_ascii_hexdigit())){return Err("GUID de energia inválido".into())}let n=|s:&str|u64::from_str_radix(s,16).map_err(|e|e.to_string());let mut data4=[0u8;8];let tail=format!("{}{}",parts[3],parts[4]);for(i,byte)in data4.iter_mut().enumerate(){*byte=n(&tail[i*2..i*2+2])? as u8;}Ok(GUID{data1:n(parts[0])? as u32,data2:n(parts[1])? as u16,data3:n(parts[2])? as u16,data4})}
pub fn active()->Result<String,String>{let mut pointer=std::ptr::null_mut();let code=unsafe{PowerGetActiveScheme(std::ptr::null_mut(),&mut pointer)};if code!=0||pointer.is_null(){return Err(format!("PowerGetActiveScheme: erro {code}"))}let result=format_guid(unsafe{&*pointer});unsafe{LocalFree(pointer as _);};Ok(result)}
pub fn plans()->Result<Value,String>{let active=active()?;let mut rows=Vec::new();for index in 0..128{let mut guid=GUID{data1:0,data2:0,data3:0,data4:[0;8]};let mut size=16;let code=unsafe{PowerEnumerate(std::ptr::null_mut(),std::ptr::null(),std::ptr::null(),16,index,&mut guid as *mut _ as *mut u8,&mut size)};if code==259{break}if code!=0{return Err(format!("PowerEnumerate: erro {code}"))}let id=format_guid(&guid);let mut bytes=0;unsafe{PowerReadFriendlyName(std::ptr::null_mut(),&guid,std::ptr::null(),std::ptr::null(),std::ptr::null_mut(),&mut bytes);};let mut name=vec![0u16;((bytes as usize+1)/2).clamp(1,32768)];let code=unsafe{PowerReadFriendlyName(std::ptr::null_mut(),&guid,std::ptr::null(),std::ptr::null(),name.as_mut_ptr() as *mut u8,&mut bytes)};let name=if code==0{String::from_utf16_lossy(&name).trim_end_matches('\0').to_string()}else{id.clone()};rows.push(json!({"id":id,"name":name,"active":id==active}));}Ok(json!(rows))}
fn write(id:&str)->Result<(),String>{let guid=parse_guid(id)?;let listed=plans()?;if !listed.as_array().is_some_and(|rows|rows.iter().any(|r|r["id"].as_str()==Some(id))){return Err("O plano já não está instalado".into())}let code=unsafe{PowerSetActiveScheme(std::ptr::null_mut(),&guid)};if code!=0{return Err(format!("O Windows recusou alterar o plano: erro {code}. A política ou o dispositivo podem não permitir esta operação."))}if active()?!=id{return Err("O plano ativo não corresponde ao pedido".into())}Ok(())}
pub fn apply(db:&Database,id:&str,expected:&str)->Result<Value,String>{parse_guid(id)?;if active()?!=expected{return Err("O plano mudou desde a pré-visualização".into())}if id==expected{return Ok(json!({"status":"unchanged"}))}let conn=db.0.lock().map_err(|e|e.to_string())?;conn.execute("INSERT INTO changes(optimization_id,previous_value,new_value,status,category) VALUES('power.scheme',?1,?2,'pending','Energia')",params![expected,id]).map_err(|e|e.to_string())?;let row=conn.last_insert_rowid();drop(conn);let result=write(id);db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status=?1,error=?2 WHERE id=?3",params![if result.is_ok(){"applied"}else{"failed"},result.as_ref().err(),row]).map_err(|e|e.to_string())?;db.log("power.apply",&json!({"change":row,"success":result.is_ok()}).to_string())?;result?;Ok(json!({"id":row,"verified":true}))}
pub fn restore(db:&Database,id:i64)->Result<Value,String>{let conn=db.0.lock().map_err(|e|e.to_string())?;let(old,new,status):(String,String,String)=conn.query_row("SELECT previous_value,new_value,status FROM changes WHERE id=?1 AND optimization_id='power.scheme'",[id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|e|e.to_string())?;if status=="restored"{return Ok(json!({"status":"restored"}))}let newer:i64=conn.query_row("SELECT COUNT(*) FROM changes WHERE optimization_id='power.scheme' AND id>?1 AND status!='restored'",[id],|r|r.get(0)).map_err(|e|e.to_string())?;drop(conn);if newer>0{return Err("Restaure primeiro a alteração de energia mais recente".into())}let current=active()?;if current!=old&&current!=new{return Err("O plano foi alterado externamente; restauro bloqueado".into())}if current!=old{write(&old)?;}db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status='restored',error=NULL WHERE id=?1",[id]).map_err(|e|e.to_string())?;db.log("power.restore",&id.to_string())?;Ok(json!({"status":"restored","verified":true}))}
#[cfg(test)]mod tests{use super::*;#[test]fn guid_is_strict(){let value="381b4222-f694-41f0-9685-ff5bb260df2e";assert_eq!(format_guid(&parse_guid(value).unwrap()),value);for bad in ["","../381b4222","381b4222-f694-41f0-9685-ff5bb260df2e;calc","{381b4222-f694-41f0-9685-ff5bb260df2e}"]{assert!(parse_guid(bad).is_err());}}}

pub fn isolated_roundtrip()->Result<Value,String>{
 if std::env::var("GITHUB_ACTIONS").as_deref()!=Ok("true")||std::env::var("RUNNER_OS").as_deref()!=Ok("Windows"){return Err("Ensaio exclusivo do runner descartável".into())}
 let original=active()?;
 struct Guard(String);impl Drop for Guard{fn drop(&mut self){let _=write(&self.0);}}
 let _guard=Guard(original.clone());let plans=plans()?;let mut results=Vec::new();
 for plan in plans.as_array().ok_or("Inventário de energia inválido")?.iter().take(8){let id=plan["id"].as_str().ok_or("Plano sem GUID")?;if id==original{continue}let db=Database::open(std::path::Path::new(":memory:"))?;let change=apply(&db,id,&original)?;if active()?!=id{return Err("A mudança de plano não foi verificada".into())}restore(&db,change["id"].as_i64().ok_or("ID de energia ausente")?)?;if active()?!=original{return Err("O plano original não foi restaurado".into())}results.push(json!({"id":id,"applied_and_restored":true}));}
 Ok(json!({"original":original,"tests":results,"status":if results.is_empty(){"not_available_single_plan"}else{"passed"}}))
}
